next_node = None
best_score = float("inf")

# Early stop if only one node remains (has to be the destination)
if len(unvisited_nodes) == 1:
    if unvisited_nodes[0] == destination_node:
        return unvisited_nodes[0]
    else:
        return None  # should not happen if path is valid

for node in unvisited_nodes:
    # Heuristic: Weighted sum of distance to current node and to destination
    # - more weight to distance to current node (0.6), less to destination (0.4)
    score = 0.6 * distance_matrix[current_node][node] + 0.4 * distance_matrix[node][destination_node]

    if score < best_score:
        best_score = score
        next_node = node

return next_node

